import axios from "axios";

// 🔥 MOST IMPORTANT FIX — enables cookies in ALL requests
axios.defaults.withCredentials = true;

const API_BASE = "http://localhost:3001";

// -------------------- LOGIN --------------------
export async function login(username, password) {
  const res = await axios.post(`${API_BASE}/api/login`, {
    username,
    password,
  });
  return res.data;
}

// -------------------- FETCH REQUESTS --------------------
export async function fetchRequests() {
  const res = await axios.get(`${API_BASE}/api/requests`);
  return res.data;
}

// -------------------- ASSIGN DRIVER --------------------
export async function assignRequest(id, assigned_to) {
  return axios.post(`${API_BASE}/api/requests/${id}/assign`, {
    assigned_to,
  });
}

// -------------------- UPDATE STATUS --------------------
export async function updateStatus(id, status) {
  return axios.post(`${API_BASE}/api/requests/${id}/status`, {
    status,
  });
}
